const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:8081";

export async function fetchProducts() {
  const res = await fetch(`${API_BASE}/api/products`);
  if (!res.ok) {
    throw new Error("Failed to fetch products");
  }
  return res.json();
}
